 4	public final class RadixSort {
 5	    private static final int RADIX = 10;
 6	
 7	    private RadixSort() {
 8	    }
 9	
10	    public static void sort(int[] values) {
11	        validateInput(values);
12	        if (values.length < 2) {
13	            return;
14	        }
15	
16	        int maxValue = findMax(values);
17	        for (int exponent = 1; maxValue / exponent > 0; exponent *= RADIX) {
18	            countingSortByDigit(values, exponent);
19	        }
20	    }
21	
22	    public static int[] sortedCopy(int[] values) {
23	        validateInput(values);
24	        int[] copy = Arrays.copyOf(values, values.length);
25	        sort(copy);
26	        return copy;
27	    }
28	
29	    private static void validateInput(int[] values) {
30	        Objects.requireNonNull(values, "values");
31	
32	        for (int value : values) {
33	            if (value < 0) {
34	                throw new IllegalArgumentException(
35	                    "Radix sort only supports non-negative integers."
36	                );
37	            }
38	        }
39	    }
40	
41	    private static int findMax(int[] values) {
42	        int maxValue = values[0];
43	        for (int index = 1; index < values.length; index++) {
44	            if (values[index] > maxValue) {
45	                maxValue = values[index];
46	            }
47	        }
48	        return maxValue;
49	    }
50	
51	    private static void countingSortByDigit(int[] values, int exponent) {
52	        int[] output = new int[values.length];
53	        int[] counts = new int[RADIX];
54	
55	        for (int value : values) {
56	            counts[digitAt(value, exponent)]++;
57	        }
58	
59	        for (int digit = 1; digit < RADIX; digit++) {
60	            counts[digit] += counts[digit - 1];
61	        }
62	
63	        for (int index = values.length - 1; index >= 0; index--) {
64	            int value = values[index];
65	            int digit = digitAt(value, exponent);
66	            output[--counts[digit]] = value;
67	        }
68	
69	        System.arraycopy(output, 0, values, 0, values.length);
70	    }
71	
72	    private static int digitAt(int value, int exponent) {
73	        return (value / exponent) % RADIX;
74	    }
